#!/usr/bin/env python3
"""What the Dependabot checksum workflow lets through to the pull request.

Most of the refusals below remove no line at all, which is exactly what the check this replaces
looked for.

    python3 -m unittest discover -s .github/scripts -p 'test_*.py'
"""

import importlib.util
import os
import shutil
import tempfile
import unittest

spec = importlib.util.spec_from_file_location(
    'check_verification_metadata',
    os.path.join(os.path.dirname(os.path.abspath(__file__)), 'check-verification-metadata.py'),
)
check = importlib.util.module_from_spec(spec)
spec.loader.exec_module(check)

A = 'a' * 64
B = 'b' * 64
C = 'c' * 64

CONFIGURATION = '''   <configuration>
      <verify-metadata>true</verify-metadata>
      <verify-signatures>false</verify-signatures>
      <trusted-artifacts>
         <trust file=".*-javadoc[.]jar" regex="true"/>
      </trusted-artifacts>
   </configuration>
'''

ACTIVITY = '''      <component group="androidx.activity" name="activity" version="1.12.4">
         <artifact name="activity-1.12.4.aar">
            <sha256 value="%s" origin="Generated by Gradle"/>
         </artifact>
      </component>
''' % A


def document(configuration=CONFIGURATION, components=ACTIVITY):
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">\n'
        + configuration + '   <components>\n' + components + '   </components>\n</verification-metadata>\n'
    )


def component(group, name, version, *artifacts):
    inner = ''.join(
        '         <artifact name="%s">\n            <sha256 value="%s" origin="Generated by Gradle"/>\n'
        '         </artifact>\n' % artifact
        for artifact in artifacts
    )
    return '      <component group="%s" name="%s" version="%s">\n%s      </component>\n' % (
        group, name, version, inner)


class CheckTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.committed = self.write('committed.xml', document())

    def tearDown(self):
        shutil.rmtree(self.dir)

    def write(self, name, text):
        path = os.path.join(self.dir, name)
        with open(path, 'w', encoding='utf-8') as f:
            f.write(text)
        return path

    def regenerated(self, text):
        return check.compare(self.committed, self.write('regenerated.xml', text))

    def refused(self, text):
        with self.assertRaises(check.Refused):
            self.regenerated(text)


class AllowedTest(CheckTest):
    def test_the_same_file_adds_nothing(self):
        self.assertEqual(self.regenerated(document()), 0)

    def test_a_new_component_with_its_checksums(self):
        added = component('androidx.core', 'core', '1.17.0', ('core-1.17.0.aar', B), ('core-1.17.0.module', C))
        self.assertEqual(self.regenerated(document(components=ACTIVITY + added)), 2)

    def test_a_new_artifact_of_a_known_component(self):
        grown = component('androidx.activity', 'activity', '1.12.4',
                          ('activity-1.12.4.aar', A), ('activity-1.12.4.module', B))
        self.assertEqual(self.regenerated(document(components=grown)), 1)

    def test_indentation_and_attribute_order_do_not_matter(self):
        squeezed = document().replace('\n', '').replace('   ', '').replace(
            'value="%s" origin="Generated by Gradle"' % A, 'origin="Generated by Gradle" value="%s"' % A)
        self.assertEqual(self.regenerated(squeezed), 0)


class TrustPolicyTest(CheckTest):
    def test_an_added_trust_exemption(self):
        loosened = CONFIGURATION.replace(
            '      </trusted-artifacts>', '         <trust group="evil"/>\n      </trusted-artifacts>')
        self.refused(document(configuration=loosened))

    def test_metadata_verification_switched_off(self):
        self.refused(document(configuration=CONFIGURATION.replace(
            '<verify-metadata>true', '<verify-metadata>false')))

    def test_an_element_added_to_the_configuration(self):
        self.refused(document(configuration=CONFIGURATION.replace(
            '   </configuration>', '      <keyring-format>armored</keyring-format>\n   </configuration>')))

    def test_a_section_next_to_the_components(self):
        self.refused(document().replace('</verification-metadata>', '<extra/></verification-metadata>'))


class ExistingChecksumsTest(CheckTest):
    def test_a_second_accepted_hash_for_a_known_artifact(self):
        self.refused(document(components=ACTIVITY.replace(
            '"Generated by Gradle"/>', '"Generated by Gradle"/>\n            <sha256 value="%s"/>' % B)))

    def test_also_trust_on_a_known_artifact(self):
        self.refused(document(components=ACTIVITY.replace(
            '"Generated by Gradle"/>',
            '"Generated by Gradle">\n               <also-trust value="%s"/>\n            </sha256>' % B)))

    def test_a_changed_checksum(self):
        self.refused(document(components=ACTIVITY.replace(A, B)))

    def test_a_removed_component(self):
        self.refused(document(components=''))

    def test_a_removed_artifact(self):
        self.refused(document(components=component(
            'androidx.activity', 'activity', '1.12.4', ('activity-1.12.4.module', B))))


class NewChecksumsTest(CheckTest):
    def with_new(self, artifact_body):
        added = ('      <component group="x" name="y" version="1">\n'
                 '         <artifact name="y-1.jar">\n%s         </artifact>\n      </component>\n' % artifact_body)
        return document(components=ACTIVITY + added)

    def test_a_new_artifact_with_also_trust(self):
        self.refused(self.with_new(
            '            <sha256 value="%s">\n               <also-trust value="%s"/>\n'
            '            </sha256>\n' % (B, C)))

    def test_a_new_artifact_with_two_hashes(self):
        self.refused(self.with_new('            <sha256 value="%s"/>\n            <sha256 value="%s"/>\n' % (B, C)))

    def test_a_new_artifact_with_a_weaker_hash(self):
        self.refused(self.with_new('            <sha1 value="%s"/>\n' % ('d' * 40)))

    def test_a_new_artifact_with_ignored_keys(self):
        self.refused(self.with_new(
            '            <sha256 value="%s"/>\n            <ignored-keys><ignored-key id="1"/></ignored-keys>\n' % B))

    def test_a_value_that_is_not_a_sha256(self):
        self.refused(self.with_new('            <sha256 value="nope"/>\n'))

    def test_a_new_component_without_artifacts(self):
        self.refused(document(components=ACTIVITY + '      <component group="x" name="y" version="1"/>\n'))


class StructureTest(CheckTest):
    def test_a_component_listed_twice(self):
        self.refused(document(components=ACTIVITY + ACTIVITY))

    def test_an_artifact_listed_twice(self):
        self.refused(document(components=component(
            'androidx.activity', 'activity', '1.12.4', ('activity-1.12.4.aar', A), ('activity-1.12.4.aar', A))))

    def test_a_component_with_an_extra_attribute(self):
        self.refused(document(components=ACTIVITY.replace('version="1.12.4"', 'version="1.12.4" extra="1"')))

    def test_malformed_xml(self):
        self.refused(document()[:-40])

    def test_an_entity_declaration(self):
        self.refused('<?xml version="1.0"?>\n<!DOCTYPE x [<!ENTITY e "e">]>\n' + document().split('\n', 1)[1])

    def test_another_root(self):
        self.refused(document().replace('verification-metadata', 'something-else'))


class MainTest(CheckTest):
    def test_a_refusal_fails_the_step(self):
        regenerated = self.write('regenerated.xml', document(components=ACTIVITY.replace(A, B)))
        self.assertEqual(check.main(['check', self.committed, regenerated]), 1)

    def test_new_checksums_pass_it(self):
        regenerated = self.write('regenerated.xml', document(
            components=ACTIVITY + component('x', 'y', '1', ('y-1.jar', B))))
        self.assertEqual(check.main(['check', self.committed, regenerated]), 0)


if __name__ == '__main__':
    unittest.main()
